 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, color, mix, smoothstep, fract, sin, dot, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE, textureLoader, fontAtlas } = ctx;
  const { Group, PlaneGeometry, Mesh } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const root = new Group();

  const atlasW = 512;
  const atlasH = 320;
  const cardWidth = 1.6;
  const cardHeight = cardWidth * (atlasH / atlasW);

  const geometry = new PlaneGeometry(cardWidth, cardHeight);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: THREE.FrontSide,
    depthWrite: false
  });

  const vUV = uv();
  const baseGradient = mix(
    color(colors.ink),
    color(colors.surface),
    smoothstep(0.0, 1.0, vUV.y)
  );

  const noise = fract(sin(dot(vUV, vec2(12.9898, 78.233))).mul(43758.5453));
  const grain = baseGradient.add(vec3(noise.sub(0.5).mul(0.05)));
  material.colorNode = grain;

  const card = new Mesh(geometry, material);
  root.add(card);

  const textItems = config.textContent ?? [];
  for (const item of textItems) {
    const copy = typeof item?.text === 'string' ? item.text : String(item?.text ?? '');
    if (!copy) continue;
    const label = fontAtlas.createText(copy, {
      fontSize: item?.typography?.fontSize ?? 39,
      color: colors.paper,
      align: 'center'
    });
    label.position.set(0, 0, 0.02);
    root.add(label);
  }

  let loadedTexture = null;
  const timelines = [];

  if (config.imageUrl) {
    textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      if (THREE.SRGBColorSpace) tex.colorSpace = THREE.SRGBColorSpace;

      const texNode = texture(tex, vUV);
      material.colorNode = mix(texNode, grain, 0.08);
    }).catch(() => {});
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    timelines.forEach((t) => { try { t.kill(); } catch {} });
    if (loadedTexture) loadedTexture.dispose();
    geometry.dispose();
    material.dispose();
  };

  return root;
}
